SELECT SQL_NO_CACHE debtorsmaster.debtorno, debtorsmaster.name, debtorsmaster.address1, debtorsmaster.address3, debtorsmaster.address4, debtorsmaster.address5, (select sum(discountedlinetotal * -1) as total from stocktrans where debtorno = debtorsmaster.debtorno) as totalspend, (select max(trandate) from stockmoves where stockmoves.debtorno = debtorsmaster.debtorno) as lastseen, (select DATEDIFF( now(), max(trandate) ) from stockmoves where stockmoves.debtorno = debtorsmaster.debtorno) as dayssince, (select transno from stockmoves where stockmoves.debtorno = debtorsmaster.debtorno order by trandate desc limit 1 ) as lastinvoice FROM debtorsmaster WHERE 1 and debtorno in (select debtorno from custbranch where defaultlocation in (select loccode from locationusers where userid ='JACK')) AND debtorsmaster.debtorno not IN ( SELECT debtorno FROM stockmoves WHERE trandate >= DATE_SUB( NOW(), INTERVAL '60' DAY ) AND trandate <= NOW() GROUP BY debtorno ) and debtorno in (select debtorno from stockmoves where trandate >= DATE_SUB( NOW(), INTERVAL '365' DAY )) LIMIT 100 OFFSET 0 